// IR kumandayla LED: 1, 2, 3 tuşları LED'leri değiştirir, 0 hepsini söndürür.
// Seri ekran her tuşun kodunu yazar; kendi kumandanın kodlarını aşağıya yaz.
#include <IRremote.hpp>

const int IR_PIN = 2;
const int LED_PINLERI[3] = {11, 10, 9};  // LED 1, LED 2, LED 3

// Tuş kodları (yaygın NEC kumanda). Seri ekranda gördüğün kodları yaz.
const uint8_t TUS_0 = 0x16;
const uint8_t TUS_1 = 0x0C;
const uint8_t TUS_2 = 0x18;
const uint8_t TUS_3 = 0x5E;

bool durum[3] = {false, false, false};

void ledDegistir(int no) {
  durum[no] = !durum[no];
  digitalWrite(LED_PINLERI[no], durum[no]);
  Serial.print("LED ");
  Serial.print(no + 1);
  Serial.println(durum[no] ? " acik" : " kapali");
}

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 3; i++) pinMode(LED_PINLERI[i], OUTPUT);
  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);  // kart LED'i (13) sinyalde yanar
  Serial.println("IR alici hazir. Kumandada bir tusa basin.");
}

void loop() {
  if (!IrReceiver.decode()) return;

  // Basılı tutunca gelen tekrar sinyallerini ve çözülemeyenleri atla.
  bool tekrar = IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT;
  if (!tekrar && IrReceiver.decodedIRData.protocol != UNKNOWN) {
    uint8_t kod = IrReceiver.decodedIRData.command;
    Serial.print("Kod: 0x");
    Serial.print(kod, HEX);
    Serial.print("  Protokol: ");
    Serial.println(getProtocolString(IrReceiver.decodedIRData.protocol));

    if (kod == TUS_1) ledDegistir(0);
    else if (kod == TUS_2) ledDegistir(1);
    else if (kod == TUS_3) ledDegistir(2);
    else if (kod == TUS_0) {
      for (int i = 0; i < 3; i++) {
        durum[i] = false;
        digitalWrite(LED_PINLERI[i], LOW);
      }
      Serial.println("Hepsi kapali");
    }
  }
  IrReceiver.resume();  // sonraki sinyali bekle
}
